import { languageTag, PUBLIC_LOCALES } from './locales';

export const SITE_ORIGIN = 'https://revelationary.online';
export const SITE_NAME = 'Revelationary';
export const SITE_EMAIL = 'info@revelationary.online';
export const SITE_LOGO = `${SITE_ORIGIN}/logo512.png`;
export const SITE_SAME_AS = [
  'https://www.facebook.com/revelationary.online/',
  'https://www.instagram.com/revelationary.online/',
];

const OPEN_GRAPH_LOCALES: Record<string, string> = {
  en: 'en_US',
  'zh-Hans': 'zh_CN',
  de: 'de_DE',
  es: 'es_ES',
  it: 'it_IT',
  cs: 'cs_CZ',
  sv: 'sv_SE',
  id: 'id_ID',
  nl: 'nl_NL',
  vi: 'vi_VN',
};

export function openGraphLocale(language = 'en'): string {
  return OPEN_GRAPH_LOCALES[language] ?? language.replace('-', '_');
}

export function organizationSchema() {
  return {
    '@type': 'Organization',
    name: SITE_NAME,
    url: `${SITE_ORIGIN}/`,
    logo: SITE_LOGO,
    email: SITE_EMAIL,
    sameAs: SITE_SAME_AS,
    knowsLanguage: Object.keys(PUBLIC_LOCALES).map((locale) => languageTag(locale)),
  };
}

export function studySchema(options: {
  url: string;
  title: string;
  description: string;
  language: string;
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'WebApplication',
    name: options.title,
    description: options.description,
    url: options.url,
    applicationCategory: 'EducationalApplication',
    isAccessibleForFree: true,
    inLanguage: options.language,
    availableLanguage: Object.keys(PUBLIC_LOCALES).map((locale) => languageTag(locale)),
    publisher: organizationSchema(),
    potentialAction: {
      '@type': 'ReadAction',
      target: `${SITE_ORIGIN}/study/`,
    },
  };
}

export function websiteSchema(options: { url: string; description: string; language?: string }) {
  return {
    '@context': 'https://schema.org',
    '@type': 'WebSite',
    name: SITE_NAME,
    url: options.url,
    description: options.description,
    inLanguage: options.language || 'en',
    isAccessibleForFree: true,
    publisher: organizationSchema(),
    potentialAction: {
      '@type': 'ReadAction',
      target: `${SITE_ORIGIN}/study/`,
    },
  };
}

export function publicDocumentSchema(options: {
  url: string;
  title: string;
  description: string;
  language: string;
  schemaType: string;
}) {
  if (options.schemaType === 'WebSite') {
    return websiteSchema(options);
  }
  return {
    '@context': 'https://schema.org',
    '@type': options.schemaType,
    name: options.title,
    description: options.description,
    inLanguage: options.language,
    url: options.url,
    isAccessibleForFree: true,
    publisher: organizationSchema(),
    ...(options.schemaType === 'ContactPage'
      ? {
          mainEntity: {
            ...organizationSchema(),
            contactPoint: {
              '@type': 'ContactPoint',
              email: SITE_EMAIL,
              contactType: 'customer support',
            },
          },
        }
      : {}),
  };
}
