import { usePublicLanguage } from '../public-site/PublicLanguage';
import React, { Suspense, useEffect, useState } from 'react';
import PublicLayout, { PublicThemeProps } from '../public-site/PublicLayout';
import GamesEntry from '../public-site/GamesEntry';
import { GAME_PAGES, gamePath } from '../public-site/routes';
import { publicRoute } from '../public-site/locales';
import type { GameKind } from '../games/types';
import '../games/games.css';

export const GAMES_SEO_TITLE = 'Free Bible Games | Daily Wordle, Verse Practice & Flashcards';
export const GAMES_TITLE = 'Bible games | Revelationary';
export const GAMES_DESCRIPTION =
  'Play daily Bible Wordle, complete Bible verses and practise scripture with multiple-choice flashcards in your chosen translation.';
export function gamesSchema(
  game: GameKind | undefined,
  urlFor: (path: string) => string,
  t: (message: string) => string = (message) => message,
  includeGuide = false,
) {
  const collectionUrl = urlFor('/games/');
  if (!game) {
    return {
      '@context': 'https://schema.org',
      '@type': 'CollectionPage',
      name: t(GAMES_TITLE),
      description: t(GAMES_DESCRIPTION),
      url: collectionUrl,
      mainEntity: {
        '@type': 'ItemList',
        itemListElement: Object.values(GAME_PAGES).map((page, index) => ({
          '@type': 'ListItem',
          position: index + 1,
          name: t(page.title),
          url: urlFor(page.path),
        })),
      },
      ...(includeGuide
        ? {
            hasPart: {
              '@type': 'Question',
              name: t('Are these Bible games free to play?'),
              acceptedAnswer: {
                '@type': 'Answer',
                text: t(
                  'Yes. All three Bible games are free to play as a guest. A signed-in account lets you save completed Wordle scores and opt into the daily leaderboard.',
                ),
              },
            },
          }
        : {}),
    };
  }
  const page = GAME_PAGES[game];
  const url = urlFor(page.path);
  const guide = gameGuides[game];
  return {
    '@context': 'https://schema.org',
    '@type': 'WebPage',
    name: t(page.title),
    description: t(page.description),
    url,
    isPartOf: { '@type': 'CollectionPage', url: collectionUrl },
    breadcrumb: {
      '@type': 'BreadcrumbList',
      itemListElement: [
        { '@type': 'ListItem', position: 1, name: t('Games'), item: collectionUrl },
        { '@type': 'ListItem', position: 2, name: t(page.title), item: url },
      ],
    },
    ...(includeGuide
      ? {
          mainEntity: {
            '@type': 'HowTo',
            name: t(guide.heading),
            description: t(guide.answer),
            step: guide.steps.map((text, index) => ({
              '@type': 'HowToStep',
              position: index + 1,
              text: t(text),
            })),
          },
          hasPart: {
            '@type': 'Question',
            name: t(guide.question),
            acceptedAnswer: { '@type': 'Answer', text: t(guide.detail) },
          },
        }
      : {}),
  };
}

const gameGuides = {
  wordle: {
    heading: 'How to play Bible Wordle',
    answer:
      'One daily Bible puzzle in your language. Five letters or Chinese characters. Six guesses.',
    steps: [
      'Enter five letters or Chinese characters using your keyboard or the on-screen keys.',
      'Use the tile feedback. A correct letter may be in the right position or elsewhere in the word.',
      'Use the clues to narrow down your next guess. The daily puzzle changes at midnight UTC.',
    ],
    question: 'Do I need an account to play Bible Wordle?',
    detail:
      'You can play as a guest. Sign in to save a completed score and choose whether to join the daily leaderboard.',
  },
  blank: {
    heading: 'How to play fill-in-the-blank Bible verses',
    answer:
      'Complete Bible verses by choosing the missing word from three options. Each round contains ten verses from your selected Bible translation.',
    steps: [
      'Choose a Bible translation and start a round.',
      'Read the verse around the blank and select the word that completes it.',
      'Review the verses you missed and read them in context in the study tool.',
    ],
    question: 'Which game helps me recall the wording of a verse?',
    detail:
      'Choose fill in the blank to practise the wording. Choose verse flashcards to practise matching passages with their Bible references.',
  },
  flashcards: {
    heading: 'How to practise with Bible verse flashcards',
    answer:
      'Bible verse flashcards ask you to match scripture with its reference. A round has ten cards and you can choose from three difficulty levels.',
    steps: [
      'Select a Bible translation and difficulty level.',
      'Read each passage and choose its book, chapter and verse from the answers shown.',
      'Review missed cards and revisit the surrounding passage in the study tool.',
    ],
    question: 'Do flashcards change my Bible reading streak?',
    detail:
      'Flashcards and fill-in-the-blank rounds are separate practice activities. They do not record a completed chapter or change your reading streak.',
  },
} satisfies Record<
  GameKind,
  { heading: string; answer: string; steps: string[]; question: string; detail: string }
>;

export default function GamesPage({
  game,
  leaderboardView = false,
  ...props
}: PublicThemeProps & {
  game?: GameKind;
  leaderboardView?: boolean;
}) {
  const { t, href, locale } = usePublicLanguage();
  const [ready, setReady] = useState(false);
  useEffect(() => {
    setReady(true);
    if (game && publicRoute(window.location.pathname).path.replace(/\/$/, '') === '/games') {
      window.history.replaceState(null, '', href(gamePath(game, leaderboardView)));
    }
  }, [game, leaderboardView, href]);
  const page = game ? GAME_PAGES[game] : null;
  const guide = game ? gameGuides[game] : null;
  const loading = <p role="status">{t('Loading game…')}</p>;
  return (
    <PublicLayout {...props}>
      <section className="games-page home-width">
        {game && (
          <nav className="games-breadcrumb" aria-label={t('Games')}>
            <a href={href('/games/')}>{t('Games')}</a>
            <span aria-hidden="true"> / </span>
            <span aria-current="page">{t(GAME_PAGES[game].title)}</span>
          </nav>
        )}
        <header className="games-heading">
          <h1>{page ? t(page.title) : locale === 'en' ? 'Bible games' : t('Games')}</h1>
          <p>{t(page?.description || GAMES_DESCRIPTION)}</p>
        </header>
        {game ? (
          <>
            {ready ? (
              <Suspense fallback={loading}>
                <GamesEntry initialGame={game} leaderboardView={leaderboardView} />
              </Suspense>
            ) : (
              loading
            )}
          </>
        ) : (
          <>
            <p className="games-intro">
              {t('A little practice, every day. Explore scripture through three free Bible games.')}
            </p>
            <div className="games-selection">
              <article>
                <span className="game-number">{t('01 / DAILY')}</span>
                <img
                  className="game-cover"
                  src="/games/wordle-illustration.webp"
                  alt={t('Green and brown word-game tiles beside an open Bible.')}
                  width="768"
                  height="512"
                  loading="lazy"
                  decoding="async"
                />
                <h2>{t('Bible Wordle')}</h2>
                <p>
                  {t(
                    'One daily Bible puzzle in your language. Five letters or Chinese characters. Six guesses.',
                  )}
                </p>
                <a className="game-card-link" href={href(gamePath('wordle'))}>
                  {t('Play today →')}
                </a>
              </article>
              <article>
                <span className="game-number">{t('02 / PRACTICE')}</span>
                <img
                  className="game-cover"
                  src="/games/blank-illustration.webp"
                  alt={t('A blue and yellow verse exercise beside an open Bible.')}
                  width="768"
                  height="512"
                  loading="lazy"
                  decoding="async"
                />
                <h2>{t('Fill in the blank')}</h2>
                <p>
                  {t(
                    'Complete a verse from your chosen translation. Pick the missing word from three answers.',
                  )}
                </p>
                <a className="game-card-link" href={href(gamePath('blank'))}>
                  {t('Complete a verse →')}
                </a>
              </article>
              <article>
                <span className="game-number">{t('03 / REMEMBER')}</span>
                <img
                  className="game-cover"
                  src="/games/flashcards-illustration.webp"
                  alt={t('Purple scripture memory cards on a warm brown study desk.')}
                  width="768"
                  height="512"
                  loading="lazy"
                  decoding="async"
                />
                <h2>{t('Verse flashcards')}</h2>
                <p>
                  {t(
                    'Match scripture with its reference in ten-card rounds, with three difficulty levels and a review of missed cards.',
                  )}
                </p>
                <a className="game-card-link" href={href(gamePath('flashcards'))}>
                  {t('Practise verses →')}
                </a>
              </article>
            </div>
            <p className="games-note">
              {t(
                'Play as a guest. Sign in to save completed Wordle scores, earn trophies and join the optional daily leaderboard. Practice games do not change your reading streak.',
              )}
            </p>
          </>
        )}
        <section className="games-guide" aria-labelledby="games-guide-heading">
          <div>
            <h2 id="games-guide-heading">
              {t(guide?.heading || 'Which Bible game should I play?')}
            </h2>
            {guide ? (
              <>
                <p>{t(guide.answer)}</p>
                <ol>
                  {guide.steps.map((step) => (
                    <li key={step}>{t(step)}</li>
                  ))}
                </ol>
              </>
            ) : (
              <p>
                {t(
                  'Play Bible Wordle for a daily word puzzle, fill in the blank to recall a verse’s wording, or use flashcards to match verses to their references.',
                )}
              </p>
            )}
          </div>
          <div>
            <h3>{t(guide?.question || 'Are these Bible games free to play?')}</h3>
            <p>
              {t(
                guide?.detail ||
                  'Yes. All three Bible games are free to play as a guest. A signed-in account lets you save completed Wordle scores and opt into the daily leaderboard.',
              )}
            </p>
            {game === 'wordle' && (
              <>
                <h3>{t('What is Bible Wordle?')}</h3>
                <p>
                  {t(
                    'Bible Wordle is a daily five-letter or Chinese-character puzzle. Play as a guest in any of the 11 Bible translations. The puzzle resets at midnight UTC. Fill-in-the-blank and flashcards do not change a reading streak.',
                  )}
                </p>
                <h3>{t('Is Bible Wordle the same as Christian Wordle?')}</h3>
                <p>
                  {t(
                    'People searching for Bible Wordle or Christian Wordle want a daily Bible word game. This page is a free in-browser puzzle. You do not need an account to play.',
                  )}
                </p>
              </>
            )}
            {game && (
              <nav aria-label={t('More Bible games')}>
                <a href={href('/games/')}>{t('All Bible games')}</a>
                {(Object.keys(GAME_PAGES) as GameKind[])
                  .filter((kind) => kind !== game)
                  .map((kind) => (
                    <a key={kind} href={href(gamePath(kind))}>
                      {t(GAME_PAGES[kind].title)}
                    </a>
                  ))}
              </nav>
            )}
          </div>
        </section>
        <p className="games-study">
          <a href={href('/study/')}>{t('Open the Bible study tool →')}</a>
        </p>
      </section>
    </PublicLayout>
  );
}
